def maxCompatibilitySum(students: list[list[int]], mentors: list[list[int]]) -> int:
    m = len(students)
    n = len(students[0])
    scores = [[0] * m for _ in range(m)]
    for i in range(m):
        for j in range(m):
            scores[i][j] = sum(1 for k in range(n) if students[i][k] == mentors[j][k])
    memo = {}
    def dfs(s_idx, mask):
        if s_idx == m: return 0
        if mask in memo: return memo[mask]
        res = 0
        for j in range(m):
            if not (mask & (1 << j)):
                res = max(res, scores[s_idx][j] + dfs(s_idx + 1, mask | (1 << j)))
        memo[mask] = res
        return res
    return dfs(0, 0)

